import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    def derivative(xs, x):
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    def newton_method(coeffs, x0, tol=1e-6, max_iter=1000):
        x = x0
        for _ in range(max_iter):
            fx = poly(coeffs, x)
            if abs(fx) < tol:
                return x
            dfx = derivative(coeffs, x)
            if abs(dfx) < 1e-10:
                break
            x = x - fx / dfx
        return x

    # Try multiple starting points to find a root
    for start in [-10, -1, 0, 1, 10]:
        try:
            root = newton_method(xs, start)
            if abs(poly(xs, root)) < 1e-6:
                return round(root, 6)
        except:
            continue

    # Fallback: use bisection if Newton fails
    def bisection(coeffs, a, b, tol=1e-6):
        fa = poly(coeffs, a)
        fb = poly(coeffs, b)
        if fa * fb > 0:
            return None
        for _ in range(100):
            c = (a + b) / 2
            fc = poly(coeffs, c)
            if abs(fc) < tol or (b - a) / 2 < tol:
                return c
            if fa * fc < 0:
                b = c
                fb = fc
            else:
                a = c
                fa = fc
        return (a + b) / 2

    # Try bisection on intervals
    for a, b in [(-10, -1), (-1, 0), (0, 1), (1, 10)]:
        root = bisection(xs, a, b)
        if root is not None and abs(poly(xs, root)) < 1e-6:
            return round(root, 6)

    return 0.0
```

