def minPath(grid, k):
    """
    Find the lexicographically minimal path of length k in a grid.
    """
    import sys
    sys.setrecursionlimit(1000000)
    N = len(grid)
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(i, j, l):
        """
        Return the minimal lexicographic tuple of length l starting from cell (i, j).
        """
        if l == 1:
            return (grid[i][j],)
        best_suffix = None
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                suffix = dfs(ni, nj, l - 1)
                if best_suffix is None or suffix < best_suffix:
                    best_suffix = suffix
        # Since a path always exists, best_suffix will not be None
        return (grid[i][j],) + best_suffix

    best_path = None
    for i in range(N):
        for j in range(N):
            path = dfs(i, j, k)
            if best_path is None or path < best_path:
                best_path = path

    return list(best_path)
