    for i in range(first_open + 1, len(string)):
        if string[i] == '[':
            second_open = i
            break

    if second_open == -1:
        return False

    # Find first ']' after second_open
    first_close = -1
    for i in range(second_open + 1, len(string)):
        if string[i] == ']':
            first_close = i
            break

    if first_close == -1:
        return False

    # Find second ']' after first_close
    second_close = -1
    for i in range(first_close + 1, len(string)):
        if string[i] == ']':
            second_close = i
            break

    if second_close == -1:
        return False

    # If we found all four, we have [ [ ] ] as a subsequence
    return True

